import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"周易口訣義 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"周易口訣義 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/koujueyi/023.md","filePath":"classics/koujueyi/023.md"}'),r={name:"classics/koujueyi/023.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><p>彖曰：頤中有物曰「噬嗑」。噬嗑而亨，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，「利用獄」也。</p><p>象曰：雷電，噬嗑。先王以明罰敕法。</p><p>初九：屨校滅趾，無咎。</p><p>象曰：「屨校滅趾」，不行也。</p><p>六二：噬膚滅鼻，無咎。</p><p>象曰：「噬膚滅鼻」，乘剛也。</p><p>六三：噬臘肉，遇毒，小吝，無咎。</p><p>象曰：「遇毒」，位不當也。</p><p>九四：噬乾胏，得金矢，利艱貞，吉。</p><p>象曰：「利艱貞吉」，未光也。</p><p>六五：噬乾肉，得黃金，貞厲，無咎。</p><p>象曰：「貞厲無咎」，得當也。</p><p>上九，何校滅耳，兇。</p><p>象曰：「何校滅耳」，聰不明也。</p><p>解讀</p><p>「噬嗑，亨，利用獄」者，噬，齧也，嗑，合也；喻人口中有物則隔人隔塞正法，使正法不行，如口中有物，間齧而必通，刑去奸邪，正法無礙，故曰「利用獄」也。象曰：「雷電，噬嗑」，雷動而威，電照而明，明動相合，故曰「噬嗑」也。「先王以明罰勑法」者，敕，整理也，謂先王以明鑑之德，刑罰兼施，整齊法度也。</p><p>初九，履校滅趾，無咎者，屨猶履也，滅，沒也；趾，足也；初九既居無位之地，是受刑之人，罪之尚微者也，若能於是時著械，沒其趾足，而因懲戒爾後改行修德，故終身無咎，故云小懲大戒，此小人之福也。</p><p>六二，噬膚滅鼻，無咎。二為得位處中，所刑者當，故曰「噬膚滅鼻」。膚是柔脆之物，喻伏罪之人，然乘剛用刑，即刑人深矣。噬過其分，以至滅鼻，雖復過深而所刑者當，故曰「無咎」。</p><p>「六三，噬臘肉遇毒，小吝，無咎」者，以陰處陽，不正行刑，罪人不伏怨生，而不乘剛，不失順道，雖有小吝，於義無咎，故曰「小吝，無咎」也。噬喻刑人，臘喻不伏，毒喻怨生。</p><p>「九四：噬乾胏，得金矢，利艱貞，吉」者，九四以陽失位，不正行刑，罪人不伏，故曰「噬乾胏」。乾胏，肉之乾者。「得金矢，利艱貞，吉」，金，剛也。矢，直也。雖刑不伏物，而能得其剛直也。既剛且直，又利艱固，不失其正，可以獲吉也。</p><p>六五：噬乾肉，得黃金，貞厲，無咎。位既不正，有所刑人，人亦不伏，猶如噬齧乾堅之肉物，所以難噬也。「得黃金，貞厲，無咎」者，黃，中也；金，剛也。以其居中履剛，得其剛正之道，剛勝也。位既不正，刑戮得當，然則居貞以危，亦免咎也。</p><p>上九：何校滅耳，兇。何，擔何也。校，枷鎖也。滅，沒也。上九喻人積惡之極，不能懲改，須至擔何枷鎖以沒其耳，將至誅滅之兇，故云「惡積而不可揜，罪大而不可解」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
